import assert from 'node:assert/strict'; import {readFileSync} from 'node:fs'; import {once} from 'node:events'; import {auditSkills} from './tools/skill-audit.mjs'; import {loadSpendLedger} from './tools/bench-budget.mjs'; import {readRunOutcome} from './tools/bench-results.mjs'; import {cmdReplay,cmdVerify} from './tools/replay.mjs'; import {validateReviewEvidence} from './tools/review-evidence.mjs';
const audit=auditSkills('.'); assert.equal(audit.ok,true); console.log(JSON.stringify({surface:'structural-audit',skills:audit.skills.length,errors:audit.findings.filter(f=>f.type==='error').length,warnings:audit.findings.filter(f=>f.type!=='error').length}));
const ledger=loadSpendLedger('.'); assert.equal(ledger.status,'ok'); assert.equal(ledger.requests.filter(r=>r.status!=='settled').length,0); assert(ledger.cumulative_tariff_usd<=1); const reports=['bench/runs/comparison-0659d78e-578c-4abc-a21d-fc00130c5218.json','bench/runs/comparison-0ff011bd-f249-47d5-b586-6ab20c82af58.json'].map(p=>JSON.parse(readFileSync(p,'utf8'))); const rows=[]; for(const report of reports) for(const row of report.runs.filter(r=>typeof r.tariff_usd==='number')) {const rawResult=JSON.parse(readFileSync(row.runDir+'/result.json','utf8')); const outcome=readRunOutcome(rawResult,report.plan.model,ledger); rows.push({task:row.task,arm:row.arm,evaluationStatus:outcome.evaluationStatus,requirementsSatisfied:outcome.score.requirementsSatisfied,missedDefects:outcome.score.missedDefects??null,falsePositives:outcome.score.falsePositives??null,tariffUsd:outcome.tariff_usd,assistantTurns:outcome.assistantTurns,stopReason:outcome.termination.stopReason});} assert.equal(rows.length,8); assert.equal(rows.filter(r=>r.evaluationStatus==='passed').length,7); assert.equal(rows.find(r=>r.task==='eval-workflow-execution-outcome'&&r.arm==='candidate-skill').evaluationStatus,'failed'); console.log(JSON.stringify({surface:'retained-native-outcomes',rows,ledger:{requests:ledger.requests.length,knownSdkTariffUsd:ledger.cumulative_tariff_usd,unsettled:0,providerInvoiceVerified:false}}));
const path='openspec/changes/skill-benefit-evaluation/evidence/native-network-proof.cassette.json'; assert.equal(cmdVerify(path),0); const cassette=JSON.parse(readFileSync(path,'utf8')); const hit=cassette.interactions[0]; const oldHandlers=new Set(process.listeners('SIGINT')); const server=cmdReplay(path,0,true); await once(server,'listening'); try {const url='http://127.0.0.1:'+server.address().port; const response=await fetch(url+hit.request.url,{method:hit.request.method,headers:{'content-type':'application/json'},body:hit.request.body}); assert.equal(response.status,hit.response.status); assert.equal(await response.text(),hit.response.body); const miss=await fetch(url+'/unrecorded-native-path',{method:'POST',body:'{}'}); assert.equal(miss.status,501); console.log(JSON.stringify({surface:'strict-genuine-network-replay',capturedStatus:response.status,exactBody:true,unrecordedStatus:miss.status,upstreamRequests:0})); } finally { await new Promise((resolve,reject)=>server.close(e=>e?reject(e):resolve())); for(const handler of process.listeners('SIGINT')) if(!oldHandlers.has(handler))process.removeListener('SIGINT',handler); }
for(const changeId of ['review-execution-integrity','skill-structure-audit','skill-benefit-evaluation']) console.log(JSON.stringify({surface:'current-native-evidence-validation',changeId,...validateReviewEvidence({root:'.',changeId,tier:'T3',baseRef:'c7db6e2'})}));

